WITH recent_orders AS (SELECT * FROM orders WHERE discount <= 0.28 AND status = 'PENDING' AND amount >= 1260), store_id_summary AS (SELECT store_id, SUM(CASE WHEN status = 'SHIPPED' THEN shipping_fee ELSE 0 END) shipped_shipping_fee, SUM(CASE WHEN status = 'COMPLETED' THEN 1 ELSE 0 END) completed_count FROM recent_orders GROUP BY store_id) SELECT * FROM store_id_summary ORDER BY completed_count DESC;
